<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Horas de projetos e tarefas avulsas';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=CompanyRequestScope::adminUrl($this,'company_time_batches');$hidden=function($action)use($esc,$company_time_batches_csrf,$request_key,$choices,$billing){foreach(['action'=>$action,'company_time_batches_csrf'=>$company_time_batches_csrf,'request_key'=>$request_key]as$k=>$v)echo '<input type="hidden" name="'.$esc($k).'" value="'.$esc($v).'">';if($billing)echo '<input type="hidden" name="origin_id" value="'.(int)$billing['origin_id'].'">';if($choices)echo '<input type="hidden" name="billing[source_kind]" value="'.$esc($choices['source_kind']).'"><input type="hidden" name="billing[client_id]" value="'.(int)$choices['client']['userid'].'">';}; ?>
