<script>(function(){const form=document.getElementById('time-batch-prepare');if(!form)return;function selected(){const tasks=new Set(),projects=new Set();form.querySelectorAll('.time-batch-timer:checked').forEach(el=>{tasks.add(el.dataset.task);projects.add(el.dataset.project);});form.querySelectorAll('[data-price-task]').forEach(el=>{el.disabled=!tasks.has(el.dataset.priceTask);});form.querySelectorAll('[data-rate-project]').forEach(el=>{el.disabled=!projects.has(el.dataset.rateProject);});}form.querySelectorAll('.time-batch-timer').forEach(el=>el.addEventListener('change',selected));selected();})();</script>
